// ProofOnce prototype — the benefits counter at 9am, but you're not behind.

// ---------- tabs ----------
document.querySelectorAll('.tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById('view-' + tab.dataset.view).classList.add('active');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
});

// ---------- vault ----------
const vaultDocs = [
  { kind: 'Income', fact: '$2,184 / mo\n3 pay stubs · Oct 2 – 31', src: 'Employer: Ridgeton Foods', stamp: 'fresh', label: 'FRESH' },
  { kind: 'Income (2nd job)', fact: '$286 / mo\nW-2 + 1 stub · Oct', src: 'Employer: Lakeside Café', stamp: 'fresh', label: 'FRESH' },
  { kind: 'Household', fact: '4 members\n2 adults · 2 minors (12, 5)', src: 'Birth certificates on file', stamp: 'fresh', label: 'FRESH' },
  { kind: 'Residency', fact: '418 N. Ash St, Apt 2\nLease · renewed 2026-09', src: 'Landlord: M. Okafor', stamp: 'aging', label: 'AGING 60d' },
  { kind: 'Medicaid ID', fact: 'Renewal due 2026-12-07\nForm OH-4400-R', src: 'County letter · photo', stamp: 'aging', label: 'DUE 21d' },
  { kind: 'SNAP award letter', fact: '$312 / mo\nRenews 2027-02-14', src: 'Benefit letter · forwarded', stamp: 'fresh', label: 'FRESH' },
];
const grid = document.getElementById('vaultGrid');
vaultDocs.forEach(d => {
  const card = document.createElement('div');
  card.className = 'doc-card';
  card.innerHTML =
    `<span class="stamp ${d.stamp}">${d.label}</span>
     <div class="doc-kind">${d.kind}</div>
     <div class="doc-fact">${d.fact.replace(/\n/g, '<br>')}</div>
     <div class="doc-src">${d.src}</div>`;
  grid.appendChild(card);
});

// ---------- 80-hour ledger ----------
const TYPE_META = {
  paid:      { label: 'Paid work (Ridgeton Foods)', cls: 'paid' },
  jobsearch: { label: 'Job search — applied ×3', cls: 'jobsearch' },
  school:    { label: 'Training — CNA coursework', cls: 'school' },
  volunteer: { label: 'Volunteer — St. Anne shelter', cls: 'volunteer' },
};
const counts = { paid: 52, jobsearch: 6, school: 4, volunteer: 2 };
const logList = document.getElementById('logList');
const meterFill = document.getElementById('meterFill');
const meterNum = document.getElementById('meterNum');
const hourStamp = document.getElementById('hourStamp');
const statementBtn = document.getElementById('statementBtn');

function total() { return counts.paid + counts.jobsearch + counts.school + counts.volunteer; }

function render() {
  const t = total();
  meterFill.style.width = Math.min(t, 100) + '%';
  meterNum.textContent = t + ' / 80 hrs';
  Object.entries({ paid: 'cPaid', jobsearch: 'cJob', school: 'cSchool', volunteer: 'cVol' }).forEach(([k, id]) => {
    document.getElementById(id).textContent = counts[k] + 'h';
  });
  const done = t >= 80;
  hourStamp.textContent = done ? 'QUALIFIED ✓' : 'IN PROGRESS';
  hourStamp.classList.toggle('done', done);
  statementBtn.disabled = !done;
  statementBtn.textContent = done
    ? 'Generate 80-Hour Statement →'
    : (80 - t) + ' more hours to qualify';
}

document.querySelectorAll('.log-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const type = btn.dataset.type, hrs = +btn.dataset.hours;
    counts[type] += hrs;
    const li = document.createElement('li');
    li.className = 'new';
    li.innerHTML = `<span><i class="dot ${TYPE_META[type].cls}"></i> ${TYPE_META[type].label}</span>
                    <span class="mono">+${hrs}h</span>`;
    logList.prepend(li);
    render();
  });
});
render();

// ---------- statement receipt ----------
statementBtn.addEventListener('click', () => {
  const t = total();
  const lines = [
    'WORK ACTIVITY STATEMENT',
    'Month: November 2026',
    '--------------------------------',
    `Paid work ......... ${counts.paid} h  (Ridgeton Foods)`,
    `Job search ........ ${counts.jobsearch} h  (applications on file)`,
    `School / training . ${counts.school} h  (CNA coursework)`,
    `Volunteer ......... ${counts.volunteer} h  (St. Anne shelter)`,
    '--------------------------------',
    `TOTAL ............. ${t} h   (required: 80)`,
    '',
    'VERDICT: QUALIFIED',
    'Generated by ProofOnce · you reviewed',
    'this before it leaves your hands.',
  ];
  showReceipt(lines.join('\n'));
});

// ---------- radar ----------
const renewals = [
  { who: 'You — Medicaid (Adult Expansion)', prog: 'OH · 6-month recert · due 2026-12-07', days: 21, badge: 'due-soon', badgeLabel: 'DUE 21d', pct: 30 },
  { who: 'You — 80-hour proof', prog: 'Nov statement · month closes 2026-11-30', days: 14, badge: 'on-track', badgeLabel: 'ON TRACK', pct: 55 },
  { who: 'You — SNAP', prog: 'OH · recert window opens 2027-01-14', days: 59, badge: 'on-track', badgeLabel: 'PREP 59d', pct: 15 },
  { who: 'J. (12) — School meals', prog: 'Free & reduced · year renewal 2027-08-01', days: 258, badge: 'on-track', badgeLabel: 'PREP 258d', pct: 8 },
];
const radarList = document.getElementById('radarList');
renewals.forEach(r => {
  const card = document.createElement('div');
  card.className = 'radar-card';
  card.innerHTML = `
    <div>
      <div class="radar-who">${r.who}</div>
      <div class="radar-prog">${r.prog}</div>
      <span class="badge ${r.badge}">${r.badgeLabel}</span>
    </div>
    <div class="radar-right">
      <div class="radar-due">${r.days}d</div>
      <div class="radar-bar"><i style="width:${r.pct}%"></i></div>
    </div>`;
  radarList.appendChild(card);
});

// ---------- mistake check ----------
document.getElementById('fixBtn').addEventListener('click', () => {
  document.querySelector('.verdict-card').style.display = 'none';
  document.querySelector('.check-row').style.display = 'none';
  document.getElementById('checkResolved').classList.remove('hidden');
});

// ---------- receipt ----------
function showReceipt(text) {
  document.getElementById('receiptText').textContent = text;
  document.getElementById('receiptVeil').classList.remove('hidden');
}
document.getElementById('receiptClose').addEventListener('click', () => {
  document.getElementById('receiptVeil').classList.add('hidden');
});
